-- =============================================================================
-- AgriProfit — Database Seed Data
-- Auto-generated from project_data CSV and GeoJSON datasets.
-- Idempotent (ON CONFLICT DO NOTHING).
-- =============================================================================

BEGIN;

-- 1. Reference: Districts
CREATE TABLE IF NOT EXISTS districts (district_id VARCHAR(10) PRIMARY KEY, state VARCHAR(60) NOT NULL, state_code VARCHAR(5) NOT NULL, district VARCHAR(60) NOT NULL, district_code VARCHAR(15) NOT NULL, latitude NUMERIC(9,6) NOT NULL, longitude NUMERIC(9,6) NOT NULL, agro_climatic_zone VARCHAR(60));

-- 2. Reference: Climate Regions
CREATE TABLE IF NOT EXISTS climate_regions (region_id VARCHAR(10) PRIMARY KEY, district_id VARCHAR(10) REFERENCES districts(district_id), state VARCHAR(60), district VARCHAR(60), latitude NUMERIC(9,6), longitude NUMERIC(9,6), agro_climatic_zone VARCHAR(60), koppen_climate_class VARCHAR(5));

-- 3. Reference: Crops Master
CREATE TABLE IF NOT EXISTS crops_master (crop_id VARCHAR(10) PRIMARY KEY, crop_name VARCHAR(80) NOT NULL, category VARCHAR(30) NOT NULL, season VARCHAR(15) NOT NULL, duration_days INT NOT NULL, water_requirement_mm INT NOT NULL, soil_type_suitable VARCHAR(40), min_temp_c NUMERIC(4,1), max_temp_c NUMERIC(4,1), ideal_temp_min_c NUMERIC(4,1), ideal_temp_max_c NUMERIC(4,1), avg_yield_kg_per_ha NUMERIC(10,1), seed_cost_per_ha_inr NUMERIC(10,2), fertilizer_cost_per_ha_inr NUMERIC(10,2), labor_cost_per_ha_inr NUMERIC(10,2), irrigation_cost_per_ha_inr NUMERIC(10,2), other_cost_per_ha_inr NUMERIC(10,2), total_input_cost_per_ha_inr NUMERIC(10,2), msp_eligible BOOLEAN NOT NULL DEFAULT FALSE, price_unit VARCHAR(10) NOT NULL, fao_item_code VARCHAR(10));

-- 4. Raw/Seed: Farmers
CREATE TABLE IF NOT EXISTS farmers (farmer_id VARCHAR(15) PRIMARY KEY, full_name VARCHAR(100) NOT NULL, gender VARCHAR(10), age INT, phone_number_masked VARCHAR(15), district_id VARCHAR(10) REFERENCES districts(district_id), state VARCHAR(60), district VARCHAR(60), village VARCHAR(60), land_owned_hectares NUMERIC(6,2), preferred_language VARCHAR(20), registration_date DATE NOT NULL);

-- 5. Raw/Seed: Farms
CREATE TABLE IF NOT EXISTS farms_aligned (farm_id VARCHAR(10) PRIMARY KEY, farmer_id VARCHAR(15) NOT NULL REFERENCES farmers(farmer_id), district_id VARCHAR(10) REFERENCES districts(district_id), state VARCHAR(60), district VARCHAR(60), latitude NUMERIC(9,6) NOT NULL, longitude NUMERIC(9,6) NOT NULL, area_hectares NUMERIC(8,2) NOT NULL, boundary_type VARCHAR(10) NOT NULL, soil_type VARCHAR(30), water_source VARCHAR(30), irrigation_type VARCHAR(20), registration_date DATE NOT NULL);

COMMIT;
